document.addEventListener('DOMContentLoaded', function () {
  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function (anchor) {
    anchor.addEventListener('click', function (e) {
      var target = document.querySelector(this.getAttribute('href'));
      if (target) { e.preventDefault(); target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    });
  });


});

window.UIUtils = {
  toggleElement: function (selector) {
    var el = document.querySelector(selector);
    if (el) el.style.display = el.style.display === 'none' ? '' : 'none';
  },
};


document.addEventListener("DOMContentLoaded", function () {

    // Cancel Button
    document.getElementById("cancelBtn").addEventListener("click", function () {

        if(confirm("Discard all changes?")){

            window.location.reload();

        }

    });

    // Reset Button
    document.getElementById("resetBtn").addEventListener("click", function () {

        if(!confirm("Reset all fields?")){

            event.preventDefault();

        }

    });

    // Preview Button
    document.getElementById("previewBtn").addEventListener("click", function () {

        window.open("<?php echo base_url(); ?>","_blank");

    });

    // Save Button
    const form=document.querySelector("form");

    form.addEventListener("submit",function(){

        document.getElementById("saveBtn").innerHTML="Saving...";

        document.getElementById("saveBtn").disabled=true;

    });

});
const offerModal = document.getElementById("offerModal");

document.getElementById("addOfferBtn").onclick = function () {
    offerModal.classList.remove("hidden");
    offerModal.classList.add("flex");
};

document.getElementById("closeOfferModal").onclick = function () {
    offerModal.classList.add("hidden");
    offerModal.classList.remove("flex");
};

document.getElementById("cancelOfferModal").onclick = function () {
    offerModal.classList.add("hidden");
    offerModal.classList.remove("flex");
};

window.onclick = function(e){
    if(e.target === offerModal){
        offerModal.classList.add("hidden");
        offerModal.classList.remove("flex");
    }
}
